T["Noch keine Mitspieler von ausserhalb der Gilde.\nWer mit dir in einer Gruppe war, landet automatisch hier."] = "Nessun giocatore esterno alla gilda ancora.\nChi è stato in gruppo con te finisce qui automaticamente."
T["Noch keine Nachrichten. Alles, was ab jetzt im Gildenchat geschrieben wird, landet hier."] = "Ancora nessun messaggio. Tutto ciò che verrà scritto nella chat di gilda da ora in poi finirà qui."
T["Noch keine Positionen."] = "Nessuna posizione ancora."
T["Noch keine Posts. Klick auf 'Neuer Schnappschuss' oder auf die Kamera in der Oasis-Leiste!"] = "Ancora nessun post. Clicca su 'Nuovo scatto' o sulla fotocamera nella barra di Oasis!"
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "Nessun punto ancora.\nAppena un ufficiale avvia un'incursione, tutti i presenti guadagnano punti impegno."
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "Nessuna ricetta conosciuta ancora.\nApri una volta la finestra della tua professione - Oasis le condivide poi automaticamente con la gilda."
T["Noch keine Rezepte geteilt.\n\nSobald jemand mit Oasis sein Berufsfenster oeffnet, erscheinen die Rezepte hier. Wer welchen Beruf hat, siehst du schon jetzt:"] = "Nessuna ricetta condivisa.\n\nAppena qualcuno con Oasis apre la finestra della professione, le ricette compaiono qui. Chi ha quale professione lo vedi già:"
T["Noch keine Spiele."] = "Nessuna partita ancora."
T["Noch keine Umfragen."] = "Nessun sondaggio ancora."
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "Nessuna conosciuta ancora - appena qualcuno con Oasis ha una quest per questa spedizione, comparirà qui."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff in der Uebersicht ueber '+' zum Katalog hinzu."] = "Ancora vuoto. Siediti a un falò e aggiungi\nil buff nella panoramica con '+' al catalogo."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff rechts ueber '+' zum Katalog hinzu."] = "Ancora vuoto. Siediti a un falò e aggiungi\nil buff a destra con '+' al catalogo."
T["Noch nichts erledigt."] = "Nulla completato ancora."
T["Noch nichts im Feed. Folge Leuten aus der Gilde - ihre Posts landen dann hier."] = "Ancora niente nel feed. Segui persone della gilda - i loro post arriveranno qui."
T["Noch nichts passiert."] = "Non è successo ancora nulla."
T["Noch nichts passiert. Geht spielen!"] = "Non è successo ancora nulla. Andate a giocare!"
T["Noch niemand - die Gilde ist informiert."] = "Ancora nessuno - la gilda è stata informata."
T["Noch niemand bekannt. Wer das Rezept hat, teilt es automatisch beim Oeffnen des Berufsfensters."] = "Ancora nessuno conosciuto. Chi ha la ricetta la condivide automaticamente aprendo la finestra della professione."
T["Noch niemand gestorben. Respekt!"] = "Ancora nessuno è morto. Rispetto!"
