T["Alle: Nie vor oder hinter Onyxia stehen (Atem/Schwanz).\nPhase 2 ab 65%: Feuerbaellen ausweichen, Welpen sofort umhauen.\nPhase 3 ab 40%: Furcht - Totem der Erdung und Furchtschutz bereit.\nTank: Onyxia mit dem Ruecken zur Wand, Kopf weg vom Raid.\nTank: Phase 3 sofort Aggro zurueckholen.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: Erst nach 3 Rueckenangriffen des Tanks voll loslegen.\nDD: Phase 2: Welpen vor Onyxia."] = "Tutti: mai davanti o dietro Onyxia (soffio/coda).\nFase 2 dal 65%: schivare le palle di fuoco, abbattere subito i cuccioli.\nFase 3 dal 40%: paura - Totem del Radicamento e Protezione dalla Paura pronti.\nDifensore: Onyxia con la schiena al muro, testa lontana dall'incursione.\nDifensore: in fase 3 riprendere subito l'aggro.\nGuaritori: il difensore ha la priorità, in fase 2 stare sparpagliati.\nDPS: attaccare a pieno solo dopo 3 attacchi alle spalle del difensore.\nDPS: fase 2: cuccioli prima di Onyxia."
T["Alle: Schwarm-Ziel: rauslaufen.\nTank: Infernal-Tank abseits.\nHeiler: Schlaf entfernen, wo moeglich.\nDD: Infernals ignorieren, alles auf den Boss."] = "Tutti: bersaglio dello sciame: uscire.\nDifensore: difensore degli Infernali in disparte.\nGuaritori: rimuovere il sonno dove possibile.\nDPS: ignorare gli Infernali, tutto sul boss."
T["Alle: Tod und Verfall sofort verlassen.\nTank: Mitte halten, bei Frostnova nicht bewegen.\nHeiler: Eisblock-Ziel schnell hochheilen.\nDD: Fernkampf weit verteilt (Eispfeil-Kette)."] = "Tutti: uscire subito da Morte e Decomposizione.\nDifensore: tenere il centro, non muoversi con Nova di Gelo.\nGuaritori: curare in fretta il bersaglio nel blocco di ghiaccio.\nDPS: a distanza ben sparpagliati (catena di Dardo di Ghiaccio)."
