T["Aus: Die Gilde sieht nur deine Charaktere, die in der Gilde sind. Bank- und Chill-Twinks bleiben privat. An: Alle deine Charaktere werden als Twinks angezeigt."] = "Disattivo: la gilda vede solo i tuoi personaggi nella gilda. Alt da banca e da relax restano privati. Attivo: tutti i tuoi personaggi appaiono come alt."
