T["Automatisch: Oasis legt alle 10 Minuten und beim Ausloggen einen Schnappschuss in den Gespeicherten Variablen ab (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Das Programm Tools/oasis_export.py liest die Datei, macht JSON daraus und kann es an eure Weboberflaeche schicken. Addons haben keinen Internetzugriff - das ist der sichere Weg."] = "Automatico: Oasis salva ogni 10 minuti e al logout un'istantanea nelle Variabili salvate (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Il programma Tools/oasis_export.py legge il file, lo converte in JSON e può inviarlo alla vostra interfaccia web. Gli addon non hanno accesso a Internet - questo è il modo sicuro."
