T["Den Download findest du in unserem Discord."] = "Trovi il download nel nostro Discord."
T["Den Knopf kannst du auch direkt an der Minimap mit der Maus verschieben."] = "Puoi anche spostare il pulsante direttamente sulla minimappa col mouse."
T["Den Raid-Simulator gibt es nur in der Entwicklerversion."] = "Il simulatore d'incursione esiste solo nella versione sviluppatore."
T["Den Raidplan bearbeiten duerfen Gildenleitung, Schlachtzugsleiter und Raid-Assistenten."] = "Il piano d'incursione può essere modificato da gestione gilda, capi incursione e assistenti."
T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "WoW non può mostrare qui l'albero dei talenti di questa classe. Il testo d'esportazione si può copiare sotto."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "Eliminare l'intera cronologia con %s? Anche i messaggi salvati vanno persi."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "L'ordine va a tutti gli artigiani con questa ricetta - chi ha tempo lo accetta."
T["Der Auftrag wird fuer alle zurueckgezogen."] = "L'ordine viene ritirato per tutti."
T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "Il committente viene avvisato che è pronto."
T["Der Auftraggeber bekommt Bescheid."] = "Il committente viene avvisato."
T["Der Basar ist leer"] = "Il bazar è vuoto"
T["Der Brachland-Chat mit seinen Spruechen"] = "La chat di Barrens con le sue battute"
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "Il client al momento non fornisce abilità - attendi un attimo dopo l'accesso."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "La bussola delle spedizioni: quale spedizione è adatta, cosa cade lì per te."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "Il nemico non era davanti a te. Era dietro di te. Tutto il tempo."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "Il capogruppo può renderti assistente."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "Il combattimento era inizialmente bloccato ed è stato elaborato in seguito."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "Il pulsante non può più essere spostato col mouse"
T["Der Link gilt fuer alle Leitungen."] = "Il link vale per tutti i capi."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "Il mercato usa i prezzi dell'addon AH Midas. Appena tu o qualcuno della gilda scansiona la casa d'aste con Midas, questa pagina si sblocca."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "La registrazione degli orari di gioco è disattiva. Attivala e Oasis impara ogni sera."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "Il grado Oasis è il grado di gilda di Oasis - sale giocando insieme, aiutando, con artigianato, eventi e distintivi."
T["Der Online-Sound dieser Person ist bei dir aus."] = "Il suono online di questa persona è disattivato per te."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "Il bordo della finestra di Oasis brilla del tuo colore"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "L'anello mostra chi è senza punti aperti."
T["Der Steinfresser"] = "Il Divoratore di Pietre"
T["Der Termin liegt in der Vergangenheit."] = "L'evento è nel passato."
T["Details"] = "Dettagli"
T["Di"] = "Mar"
T["Diagnose und Abgleich"] = "Diagnosi e sincronizzazione"
T["Diamant"] = "Diamante"
T["Diamant = Verbannen (Hexenmeister)"] = "Diamante = Esilio (stregone)"
T["Die Bank besucht. Mal kurz nachzaehlen."] = "Visitata la banca. Diamo una ricontata."
T["Die Bannliste ist leer."] = "La lista dei bannati è vuota."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "L'input della chat era stato toccato da Oasis (es. pulsante 'Sussurra'), poi è stato digitato /target."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "L'input della chat era stato toccato da Oasis (es. pulsante 'Sussurra'), poi vi è stato digitato un comando /cast."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "L'input della chat era stato toccato da Oasis, poi è stato digitato /focus."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "L'input della chat era stato toccato da Oasis, poi è stato digitato un comando d'incantesimo."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "Le mappe delle spedizioni non hanno coordinate. Clicca qui, poi sul punto della mappa dove ti trovi ora. Fatto in due punti lontani, Oasis mostra te e il tuo gruppo sulla mappa - per tutta la gilda."
T["Die Gilde bekommt Bescheid"] = "La gilda viene avvisata"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "La gilda vede a chi rispondi. Predefinito: disattivo"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "La gilda vede il tuo fuoco per %d minuti sulla mappa."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "La gilda vede nella cronaca ciò che hai raggiunto"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "La gilda al momento non cerca nulla da questa spedizione."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "La gilda non assegna ancora punti bottino - i tuoi valori appaiono appena il capo incursione avvia un'incursione."
T["Die Gildenbank wurde noch nicht gelesen"] = "La banca di gilda non è ancora stata letta"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "La gestione gilda nomina capi incursione e assistenti in Corona > Moduli > Incursioni & bottino (nomi o da grado di gilda). Nell'incursione in corso contano anche capo incursione e assistenti."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "La gestione gilda nomina i capi incursione in Corona > Moduli > Incursioni & bottino. Nell'incursione in corso contano anche capo incursione e assistenti."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "La gestione gilda nomina i capi incursione in Corona > Moduli > Incursioni & bottino. Nell'incursione in corso conta anche il capo incursione."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "La gestione gilda consente ricerche di gruppo solo da un grado più alto."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "La gestione gilda consente sondaggi solo da un grado più alto."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "La gestione gilda ha disattivato la ricerca compagni."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "La gestione gilda ha disattivato gli inviti aperti - sfida qualcuno direttamente."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "La gestione gilda stabilisce in Corona > Moduli quali gradi possono farlo."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "La ricerca gilde di WoW aiuta a trovare - neutrale, senza pubblicità."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "Il limite lo stabilisce solo il maestro di gilda. Grado 1 = maestro di gilda."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "I pulsanti scrivono il comando nella riga di chat - viene eseguito solo con Invio."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "Le scorciatoie sono anche nei Tasti di WoW sotto AddOns > Oasis. Esc chiude la finestra di Oasis (non in combattimento - lì Esc appartiene al gioco)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "Le scorciatoie sono anche nei Tasti di WoW sotto AddOns > Oasis. Esc chiude la finestra di Oasis, se ci hai cliccato per ultima."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "La barra scorre via verso l'alto; porta il mouse al bordo superiore e scende (solo se agganciata in alto)"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "La riga delle prenotazioni appare solo se sei in un gruppo o in un'incursione"
T["Die Waechter der Sande"] = "I Guardiani delle Sabbie"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "Aperta la mappa del mondo. Dov'era di nuovo il nord?"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "La barra vera in alto mostra subito ogni modifica"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "I primi 20 di Tempra danno 1 ciascuno, ogni punto in più 10 salute."
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "Più corse da spirito della gilda. Il cimitero ha una panchina col tuo nome."
T["Die meisten Screenshots der Gilde"] = "Più screenshot della gilda"
T["Die meisten Tode der letzten 7 Tage"] = "Più morti degli ultimi 7 giorni"
T["Die meisten vollen Taschen der Gilde"] = "Più borse piene della gilda"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "L'annuncio più recente resta 3 giorni in cima alla panoramica."
T["Die vergessenen Teiche"] = "Gli Stagni Dimenticati"
