T["Nichts passt zu diesen Filtern."] = "Nulla corrisponde a questi filtri."
T["Nichts passt zum Filter"] = "Nulla corrisponde al filtro"
T["Nichts verworfen."] = "Nulla scartato."
T["Nichts zu pruefen."] = "Nulla da controllare."
T["Nie"] = "Mai"
T["Niemand aus dem Vorschlag ist online."] = "Nessuno della proposta è online."
T["Niemand frei: alle passenden Charaktere sind gebunden, zu niedrig oder nicht freigeschaltet."] = "Nessuno libero: tutti i personaggi adatti sono vincolati, troppo bassi o non sbloccati."
T["Niemand gestorben - sauber gespielt."] = "Nessuno è morto - giocato pulito."
T["Niemand gestorben."] = "Nessuno è morto."
T["Niemand in der Gilde hat diesen Beruf eingetragen."] = "Nessuno nella gilda ha registrato questa professione."
T["Niemand in der Gilde hat etwas mit diesem Namen."] = "Nessuno nella gilda ha qualcosa con questo nome."
T["Niemand in der Gruppe kann ihn geben"] = "Nessuno nel gruppo può darlo"
T["Niemand in diesem Filter - sehr gut!"] = "Nessuno in questo filtro - ottimo!"
T["Niemand ist so lange offline."] = "Nessuno è offline da così tanto."
T["Niemand sonst in der Gilde"] = "Nessun altro nella gilda"
T["Niemand steht kurz vor Respektvoll oder Ehrfuerchtig (ab 75 %)."] = "Nessuno è vicino a Riverito o Osannato (dal 75 %)."
T["Niemand. Stummschalten geht per Rechtsklick auf einen Namen im Gildenchat."] = "Nessuno. Silenzia qualcuno con clic destro su un nome nella chat di gilda."
T["Ninja-Markierung entfernen"] = "Rimuovi segno ninja"
T["Noch aus"] = "Ancora off"
T["Noch gesperrt"] = "Ancora bloccato"
T["Noch hat niemand Material beigetragen."] = "Nessuno ha ancora contribuito con materiali."
T["Noch kein Highlight - die Woche ist jung."] = "Ancora nessun momento clou - la settimana è giovane."
T["Noch kein Kampf ausgewertet"] = "Nessun combattimento ancora analizzato"
T["Noch kein Muster - dafuer braucht es mehrere Versuche."] = "Ancora nessuno schema - servono più tentativi."
T["Noch kein Ready-Check"] = "Ancora nessun controllo pronti"
T["Noch kein Ready-Check gelaufen."] = "Nessun controllo pronti ancora eseguito."
T["Noch kein Scan - sobald jemand mit Midas scannt, stehen hier Schnaeppchen."] = "Nessuna scansione ancora - appena qualcuno scansiona con Midas, qui compaiono gli affari."
T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "Ancora nessun evento - segnala il tuo interesse, così la guida incursioni sa quando va bene."
T["Noch kein Tod - weiter so!"] = "Ancora nessuna morte - continua così!"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "Nessuna morte di un nemico raro ancora registrata."
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "Nessun tempo di recupero ancora condiviso - chi ha Trasmutazione, Lunastoffa o una Saliera compare qui."
T["Noch keine Abzeichen"] = "Ancora nessuna medaglia"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "Nessun equipaggiamento ancora noto - prendi di mira e ispeziona i giocatori vicini (Oasis ispeziona automaticamente i compagni nel gruppo)."
T["Noch keine Berufe gelernt."] = "Nessuna professione ancora appresa."
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "Nessun bottino da questa spedizione ancora nel registro della gilda."
T["Noch keine Beute erfasst"] = "Nessun bottino ancora registrato"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "Ancora nessun candidato. Inserisci un nome sopra - clic sullo stato per avanzare."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "Ancora nessun dato - l'equipaggiamento arriva con la prossima sincronizzazione degli utenti Oasis."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "Ancora nessun dato - i membri inviano la loro misurazione ogni 15 min (da questa versione)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Ancora nessun dato - apri una volta la finestra delle collezioni o porta cavalcature e mascotte nella borsa. Appena membri della gilda con Oasis sono online, compaiono qui."
T["Noch keine Daten von der Gilde."] = "Ancora nessun dato dalla gilda."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "Ancora nessun dato. Appena membri della gilda entrano con Oasis, i loro ID incursione compaiono qui."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "Nessuna run di spedizione ancora registrata."
T["Noch keine Dungeons geplant."] = "Nessuna spedizione ancora pianificata."
T["Noch keine Eintraege."] = "Ancora nessuna voce."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "Ancora nessuna emoji usata - i preferiti dalla selezione emoji compaiono qui."
T["Noch keine Favoriten - Diamant anklicken."] = "Ancora nessun preferito - clicca il diamante."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "Ancora nessun preferito - stella o clic destro su un suono."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "Ancora nessun preferito.\nClic destro su un'emoji per salvarla qui."
T["Noch keine Fluesternachrichten."] = "Ancora nessun sussurro."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "Ancora nessun sussurro. Scrivi a qualcuno della gilda!"
T["Noch keine Fraktionen entdeckt."] = "Nessuna fazione ancora scoperta."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "Ancora nessun obiettivo di gilda. Crea il primo - es. un'arma leggendaria o materiali per l'incursione."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "Ancora nessun rapporto di combattimento. Dopo il primo boss qui compare ogni tentativo - con cronologia delle morti e schemi ricorrenti."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "Ancora nessun rapporto di combattimento. Dopo il primo boss qui compare ogni tentativo."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "Ancora nessun candidato. Gioca con persone fuori dalla gilda - chi è senza gilda e ben valutato finisce qui."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "Ancora nessuna combo.\nMaiusc+clic su più emoji, poi Ricorda."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "Ancora nessun contatto. Fai gruppo con altri utenti Oasis - Oasis li ricorda qui, anche senza gilda."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "Ancora nessuna tappa. Sali di livello, impara professioni - qui nasce la tua storia."
T["Noch keine Meldungen aus der Gilde."] = "Ancora nessuna segnalazione dalla gilda."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "Ancora nessun momento - gioca e basta, Oasis prende nota."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "Ancora nessun messaggio nella chat ufficiali. Tutto ciò che da ora viene scritto nel canale /o compare qui."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "Ancora nessuna posizione - la mappa si riempie appena i membri con Oasis sono in giro."
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "Ancora nessun prezzo. Appena qualcuno scansiona la casa d'aste con Midas, compaiono qui."
T["Noch keine Profile gespeichert."] = "Nessun profilo ancora salvato."
T["Noch keine Punkte"] = "Ancora nessun punto"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "Ancora nessun giorno d'incursione registrato. Il capo incursione (con Oasis) li registra automaticamente a ogni boss ucciso."
T["Noch keine Regeln"] = "Ancora nessuna regola"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "Ancora nessuna regola. Scegli un modello rapido o creane una tua sopra."
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "Ancora nessun dato reputazione. Arrivano automaticamente appena i membri con Oasis sono online."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Ancora nessuna collezione condivisa. Compaiono qui appena i membri della gilda con Oasis sono online."
T["Noch keine Sets."] = "Ancora nessun set."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "Ancora nessun avvistamento. Appena qualcuno con Oasis vede un nemico raro, compare qui."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "Ancora nessun orario di gioco noto. Oasis impara ogni sera in cui sei online - e adotta i profili degli altri."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "Ancora nessuna ricerca. Inserisci i livelli e clicca \"Cerca\" - i giocatori con gilda vengono nascosti."
T["Noch keine Taktiken."] = "Ancora nessuna tattica."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "Ancora nessuna tattica. La guida incursioni può creare una breve tattica per boss - tutti la vedono qui e la ricevono quando prendono di mira il boss."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "Nessun talento ancora noto. I membri con Oasis li condividono automaticamente; altri giocatori: prendili di mira e ispezionali (clic destro > Ispeziona) o riapri qui con il bersaglio."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "Ancora nessuna assegnazione - compaiono qui appena la guida incursioni distribuisce il bottino."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "Ancora nessun valore - dopo il prossimo combattimento qui compare chi è in testa."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "Ancora nessun giorno preferito - indica quando puoi."
T["Noch keine Wunschtage gemeldet."] = "Nessun giorno preferito ancora segnalato."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "Ancora nessun obiettivo. Creane uno sopra - Oasis lo spunta automaticamente."
T["Noch keine Zusagen - sei der Erste!"] = "Ancora nessuna adesione - sii il primo!"
T["Noch keine eigene Beute"] = "Ancora nessun bottino tuo"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Ancora nessun bottino tuo registrato (da qualità 'Raro', regolabile)."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "Non ancora iscritto - scegli il tuo ruolo sotto"
T["Noch nicht bereit"] = "Non ancora pronto"
T["Noch nicht fuer die Gilde uebernommen:"] = "Non ancora applicato per la gilda:"
T["Noch nicht kalibriert - Kalibrieren?"] = "Non ancora calibrato - calibrare?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "Ancora nulla nella lista desideri.\nAggiungi sopra ciò che ti serve - tutti con Oasis lo vedono nei tooltip e durante il bottino."
T["Noch nichts aufgezeichnet."] = "Ancora nulla registrato."
T["Noch nichts benutzt."] = "Ancora nulla usato."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "Ancora nulla bloccato. Appena WoW blocca Oasis, qui compare quale funzione e cosa ha fatto Oasis poco prima."
T["Noch nichts eingelesen"] = "Ancora nulla letto"
T["Noch nichts geangelt."] = "Ancora nulla pescato."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "Ancora nulla salvato - clic destro su un messaggio: Ricorda messaggio."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "Ancora non è successo nulla - partite e fate la storia!"
T["Noch nichts reserviert"] = "Ancora nulla prenotato"
T["Noch nichts reserviert - ein Item pro Termin."] = "Ancora nulla prenotato - un oggetto per evento."
T["Noch nichts reserviert."] = "Ancora nulla prenotato."
T["Noch nichts verkauft."] = "Ancora nulla venduto."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "Ancora nulla distribuito. Appena una regola si applica, compare qui."
T["Noch nie direkt mit dir abgeglichen"] = "Mai sincronizzato direttamente con te"
T["Noch niemand angefluestert."] = "Non hai ancora sussurrato a nessuno."
T["Noch niemand aus der Gilde hat es uebrig."] = "Nessuno nella gilda ce l'ha ancora in più."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "Nessuno nella gilda con la tua specializzazione condivide ancora i talenti (gli utenti Oasis li condividono automaticamente)."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Nessuno è uscito da quando Oasis registra."
T["Noch niemand gemeldet - sei der Erste!"] = "Ancora nessuno iscritto - sii il primo!"
T["Noch niemand sonst kennt das Rezept."] = "Nessun altro conosce ancora la ricetta."
T["Noch niemand teilt seine Handelsbilanz."] = "Nessuno condivide ancora il proprio bilancio commerciale."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "Nessuno condivide ancora il proprio bilancio commerciale. Attiva 'Condividi bilancio' sotto per iniziare."
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "Nessuno condivide ancora pezzi scambiabili con Oasis. Più membri usano Oasis, più si riempie qui."
T["Noch zu uebergeben"] = "Ancora da consegnare"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "Dati insufficienti per un orario di punta"
T["Normal"] = "Normale"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "Normalmente Oasis avvisa solo per le ricerche che hai ancora aperte tu"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "Nota (classe, contatto, impressione ...)"
T["Notiz an den Plundermeister (optional)"] = "Nota al responsabile del bottino (facoltativa)"
T["Notiz der Gildenleitung"] = "Nota della guida della gilda"
T["Notiz von %s: %s"] = "Nota di %s: %s"
T["Notiz zu %s"] = "Nota su %s"
T["Notiz zur Person"] = "Nota sulla persona"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "Nota per la ricerca (orario, punto d'incontro) ..."
T["Notizen sehen und schreiben nur Offiziere."] = "Solo gli ufficiali vedono e scrivono le note."
T["Nur %s"] = "Solo %s"
T["Nur Abende vorschlagen"] = "Proponi solo serate"
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "Solo banner e tre colonne (chi è online, cosa succede, prossimamente) - senza riquadri né riga dei momenti clou"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "Solo spedizioni il cui bottino è migliore del tuo equipaggiamento indossato."
T["Nur Eintraege dieser Person"] = "Solo le voci di questa persona"
T["Nur Farbverlauf"] = "Solo sfumatura"
T["Nur Gegner im Kampf"] = "Solo nemici in combattimento"
T["Nur Gildenleitung"] = "Solo guida della gilda"
T["Nur Gruppenquests beruecksichtigen"] = "Considera solo missioni di gruppo"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "Segnala solo i falò nella mia zona"
T["Nur Mains ab Level"] = "Solo main dal livello"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "Solo i membri fino a questo grado possono avviare una ricerca gruppo (10 = tutti)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "Solo i membri fino a questo grado possono avviare un nuovo sondaggio (10 = tutti)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Solo membri con Oasis. Vengono condivisi oggetti missione aperti, oggetti missione in più e missioni condivisibili."
T["Nur Oasis-Spieler"] = "Solo giocatori Oasis"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Solo giocatori Oasis: ognuno la vede nella propria lingua."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "Solo ufficiali e guida della gilda vedono questo canale (/o)."
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "Solo responsabile del bottino, capo o assistenti possono distribuire."
T["Nur Rezepte, die du selbst kannst"] = "Solo ricette che conosci tu"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "Solo ricette che qualcuno online può creare ora"
T["Nur Upgrades"] = "Solo miglioramenti"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "Solo al proprio gruppo, per la mappa della spedizione"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "Solo visualizzazione - modifica: guida, capi incursione, assistenti incursione"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "Solo visualizzazione - disegna il capo incursione"
T["Nur auf diesem PC"] = "Solo su questo PC"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "Solo nascosto - clicca qui per tornare."
T["Nur bei dir"] = "Solo per te"
T["Nur bei dir gespeichert"] = "Salvato solo per te"
T["Nur bei gleicher Klasse und Spezialisierung."] = "Solo con stessa classe e specializzazione."
T["Nur das Noetigste"] = "Solo l'essenziale"
T["Nur der Gildenmeister kann das aendern."] = "Solo il maestro di gilda può modificarlo."
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "Solo il maestro di gilda, al massimo 10 gradi."
T["Nur der Gruppenleiter kann eine Suche starten."] = "Solo il capogruppo può avviare una ricerca."
T["Nur der Gruppenleiter kann suchen"] = "Solo il capogruppo può cercare"
T["Nur die Gildenleitung kann das aendern."] = "Solo la guida della gilda può modificarlo."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "Solo la guida della gilda può azzerare la classifica deathroll."
T["Nur die wichtigsten Bereiche sind an."] = "Sono attive solo le sezioni più importanti."
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "Solo questa persona lo sente (se ha Oasis)."
T["Nur diesen Abschnitt posten"] = "Pubblica solo questa sezione"
T["Nur fehlende"] = "Solo mancanti"
T["Nur fuer Anfuehrer und Assistenten"] = "Solo per capi e assistenti"
T["Nur fuer Offiziere"] = "Solo per ufficiali"
T["Nur fuer Schlachtzugsleiter"] = "Solo per capi incursione"
T["Nur fuer Schlachtzugsleiter & Assistenz"] = "Solo per capi incursione e assistenti"
T["Nur fuer Umfragen, die du gestartet oder bei denen du abgestimmt hast"] = "Solo per i sondaggi che hai avviato o in cui hai votato"
T["Nur fuer den Schlachtzugsleiter"] = "Solo per il capo incursione"
T["Nur fuer dich sichtbar - steht im Kopf des Gespraechs mit %s."] = "Visibile solo a te - in cima alla conversazione con %s."
T["Nur fuer dich: nach dem Kampf eine Zeile mit Dauer und erstem Tod"] = "Solo per te: dopo il combattimento una riga con durata e prima morte"
T["Nur fuer die Fehlersuche. Standard: aus"] = "Solo per il debug. Predefinito: off"
T["Nur fuer die Gildenleitung"] = "Solo per la guida della gilda"
T["Nur fuers Aussehen"] = "Solo per l'aspetto"
T["Nur guenstig"] = "Solo economici"
T["Nur handelbare (nicht seelengebundene) Teile. Werte nach Klasse und Rolle wie beim Verbesserungs-Pfeil; Bank zaehlt erst nach einmal Oeffnen."] = "Solo pezzi scambiabili (non vincolati all'anima). Valutati per classe e ruolo come la freccia di miglioramento; la banca conta solo dopo averla aperta una volta."
T["Nur in der offenen Welt; kann viele Eintraege erzeugen"] = "Solo nel mondo aperto; può generare molte voci"
T["Nur in einer Gruppe und mit der Quest im Log."] = "Solo in un gruppo e con la missione nel registro."
T["Nur in einer Gruppe."] = "Solo in un gruppo."
T["Nur mein Gebiet"] = "Solo la mia zona"
T["Nur meine"] = "Solo i miei"
T["Nur mit Helfern"] = "Solo con aiutanti"
T["Nur mit Upgrades"] = "Solo con miglioramenti"
T["Nur neue"] = "Solo nuovi"
T["Nur offene Challenges, die zu deinen Charakteren passen (Klassen, Berufe) - plus alle Dungeons, Raids, PvP und Abenteuer."] = "Solo sfide aperte adatte ai tuoi personaggi (classi, professioni) - più tutte le spedizioni, incursioni, PvP e avventure."
T["Nur ohne Belohnungs-Auswahl und ohne Kosten. Shift = aussetzen."] = "Solo senza scelta di ricompensa e senza costi. Maiusc = salta."
T["Nur online"] = "Solo online"
T["Nur von Leitern, bei denen du ueber Oasis angefragt hast"] = "Solo dai capi a cui hai chiesto tramite Oasis"
T["Nur von Oasis-Nutzern"] = "Solo da utenti Oasis"
T["Nur von Oasis-Nutzern, 30 Tage"] = "Solo da utenti Oasis, 30 giorni"
T["Nur wenn online"] = "Solo se online"
T["OFFEN"] = "APERTO"
T["OK"] = "OK"
T["Oasigram-Beitraege"] = "Post di Oasigram"
T["Oasis %s ist da"] = "Oasis %s è disponibile"
T["Oasis %s%s ist da - du hast noch %s. Bitte im Discord herunterladen."] = "Oasis %s%s è disponibile - tu hai ancora %s. Scaricalo dal Discord."
T["Oasis antwortet automatisch auf pc / preis mit Item-Link im Gildenchat"] = "Oasis risponde automaticamente a pc / prezzo con un link oggetto nella chat di gilda"
T["Oasis begleitet %s ab heute (Stufe %d)"] = "Oasis accompagna %s da oggi (livello %d)"
T["Oasis beim Einloggen oeffnen"] = "Apri Oasis all'accesso"
T["Oasis bekannt machen"] = "Fai conoscere Oasis"
T["Oasis belegt gerade %s (Kern + geladene Module)."] = "Oasis occupa ora %s (nucleo + moduli caricati)."
T["Oasis belegt gerade %s."] = "Oasis occupa ora %s."
T["Oasis fasst deine Charaktere in der Gilde zu einem Spieler zusammen. Spaeter aenderbar unter Einstellungen > Profil & Sichern."] = "Oasis raggruppa i tuoi personaggi nella gilda in un unico giocatore. Modificabile in seguito in Impostazioni > Profilo e backup."
T["Oasis funktioniert trotzdem fuer dich: dein Profil, Ziele, Dungeons und Sammlungen sind da."] = "Oasis funziona comunque per te: profilo, obiettivi, spedizioni e collezioni ci sono."
T["Oasis hatte Blizzard-Knoepfe (Aktionsleisten, Taschen, Tooltip, Chat) beruehrt (ab 0.5.504 behoben - bitte Oasis aktualisieren)."] = "Oasis aveva toccato pulsanti Blizzard (barre azioni, borse, tooltip, chat) (risolto dalla 0.5.504 - aggiorna Oasis)."
T["Oasis ist bereit"] = "Oasis è pronto"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "Oasis può fare molto. Scegli cosa vuoi usare - il resto resta spento per ora e si può attivare in qualsiasi momento in 'Scopri'."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "Dopo ogni combattimento Oasis legge il misuratore danni integrato di Blizzard - anche nelle istanze."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "Dopo ogni combattimento Oasis legge il misuratore danni integrato di Blizzard - in WoW Forever il registro di combattimento è bloccato per gli addon. I compagni devono avere Oasis dalla 0.5.577. I valori cifrati da Blizzard (es. nelle istanze) non contano."
T["Oasis oeffnen / schliessen"] = "Apri / chiudi Oasis"
T["Oasis ohne Gilde"] = "Oasis senza gilda"
T["Oasis tauscht Daten nur mit Gildenmitgliedern, die Oasis auch haben. Im Kampf und in Instanzen pausiert der Austausch."] = "Oasis scambia dati solo con i membri della gilda che hanno anch'essi Oasis. In combattimento e nelle istanze lo scambio è in pausa."
T["Oasis tauscht realmweit Version und Fehlerberichte mit anderen Oasis-Nutzern aus."] = "Oasis scambia versione e segnalazioni di errore con altri utenti Oasis su tutto il reame."
T["Oasis tauscht realmweit Version und Fehlerberichte mit anderen Oasis-Nutzern aus. Abschalten: Einstellungen > Profil & Sichern."] = "Oasis scambia versione e segnalazioni di errore con altri utenti Oasis su tutto il reame. Disattiva: Impostazioni > Profilo e backup."
T["Oasis warnt dich, wenn diese Person dir schreibt oder in deiner Gruppe ist."] = "Oasis ti avvisa quando questa persona ti scrive o è nel tuo gruppo."
