T["Wenn jemand online kommt"] = "Quando qualcuno si connette"
T["Wer"] = "Chi"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "Chi invia dati rifiutati dagli altri (senza permessi, autore falsificato, voci inventate). Un Oasis non modificato non lo fa praticamente mai - un indizio, non una prova."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "Chi segnala interesse appare qui in un posto adatto. Se c'è un evento, ti iscrivi direttamente sulla mappa."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "Chi nella gilda ha l'oggetto nella lista desideri"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "Chi vede la sezione nella navigazione (la guida della gilda vede sempre tutto)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "Chi ha lasciato la gilda o è stato rimosso. Se qualcuno torna, Oasis lo segnala alla guida della gilda."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "Chi vede la corona in alto. Senza permessi è grigia e apre solo un'anteprima."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "Chi può fissare un messaggio in cima alla chat di gilda"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "Chi può invitare non è ancora noto - accedi una volta con il tuo main, poi Oasis memorizza la guida della gilda."
T["Wer geht mit nach %s? Ich suche %s"] = "Chi viene a %s? Cerco %s"
T["Wer hat ...?"] = "Chi ha ...?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "Chi ha l'oggetto missione che ti serve? E chi puoi aiutare?"
T["Wer hat was bekommen"] = "Chi ha ricevuto cosa"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "Chi può registrare punti (partecipazione/bottino) nell'incursione."
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "Chi ha quali buff nel gruppo o nell'incursione - e cosa manca"
T["Wer ist bereit? Ampeln je Spieler"] = "Chi è pronto? Semafori per giocatore"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "Chi è già vincolato questa settimana, chi è libero e sbloccato - main e alt"
T["Wer ist online"] = "Chi è online"
T["Wer ist online?"] = "Chi è online?"
T["Wer ist wann online"] = "Chi è online quando"
T["Wer ist wie weit"] = "Chi è a che punto"
T["Wer kann was herstellen, Markt, Gildenbank"] = "Chi sa creare cosa, mercato, banca di gilda"
T["Wer koennte mit: %s"] = "Chi potrebbe venire: %s"
T["Wer koennte mit?"] = "Chi potrebbe venire?"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "Chi c'è spesso e ha ricevuto poco ha la precedenza su 'Necessità'. Ogni settimana una parte dei punti scade."
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "Chi si propone con il ruolo adatto viene invitato subito nel tuo gruppo."
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "Chi sta dove con quale fazione? Vicino all'obiettivo, farmare insieme, progresso di questa settimana"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "Chi infligge di più, cura di più, incassa di più?"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "Chi fa parte della guida della gilda lo decide il capogilda in Corona > Gilda."
T["Werbung"] = "Pubblicità"
T["Werte"] = "Valori"
T["Werte bringen deiner Rolle nichts"] = "I valori non servono al tuo ruolo"
T["Werte nur zur Info"] = "Valori solo informativi"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "Valori, annuario, obiettivo giornaliero, record e avventure del tuo personaggio."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "Valori: +cure, intelletto, spirito, rigen. mana;Arma: bastone o arma a una mano + mano secondaria con cure;Cure: Rinvigorimento e Ricrescita in anticipo, Tocco Curativo per colpi grandi;Suggerimento: Innervazione per il mana, Rinascita per i guaritori caduti"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "Valori: +cure, intelletto, critico magico (Illuminazione restituisce mana), rigen. mana;Arma: arma a una mano + mano secondaria/scudo con cure;Cure: Lampo di Luce per danni piccoli, Luce Sacra (rango basso) per colpi grandi;Suggerimento: distribuisci benedizioni, Protezione Divina se vieni attaccato"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "Valori: +cure, rigen. mana (MP5), intelletto - lo spirito serve poco;Arma: arma a una mano + scudo con cure;Cure: Catena di Guarigione per i gruppi, Onda Curativa (rango basso) per il tank;Suggerimento: piazza il Totem della Fonte di Mana, Scudo di Terra sul tank"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "Valori: +cure, spirito (Meditazione: rigenerazione anche lanciando), intelletto, rigen. mana;Arma: bastone o arma a una mano + mano secondaria con cure, bacchetta;Cure: Rinnovamento e Parola del Potere: Scudo in anticipo, Cura Superiore (rango basso) per il tank;Suggerimento: Preghiera di Guarigione per il gruppo, Svanire con aggro"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "Valori: armatura (la Forma d'Orso la moltiplica), tempra, agilità (schivata + armatura);Arma: irrilevante per il danno - contano solo i valori (bastone/arma ad asta con tempra);Rotazione: Maciullare, Fendente per i gruppi, Ruggito Demoralizzante;Suggerimento: forza per più minaccia, Infuriare all'inizio"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "Valori: forza (1 punto = 2 PA), agilità (PA + critico), critico, colpire fino a +9 %;Arma: irrilevante per il danno - contano solo i valori;Rotazione: Graffio/Lacerazione per punti combo, poi Morso Feroce;Suggerimento: powershift (rientrare in forma) per energia, balza fuori dalla furtività"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "Valori: forza (1 punto = 2 PA), critico (attiva Raffica = colpi più rapidi), colpire fino a +9 %;Arma: arma a due mani lenta - Furia del Vento colpisce per colpo, quindi più lenta = più danno;Rotazione: Arma Furia del Vento, Assalto Tempestoso, Scossa di Terra;Suggerimento: Totem della Forza della Terra e Totem Furia del Vento per il gruppo"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "Valori: forza (1 punto = 2 PA), critico, colpire fino a +9 %;Arma: arma a due mani lenta - Sigillo e Giudizio agiscono per colpo;Rotazione: Sigillo della Rettitudine/del Comando, Giudizio, rinnova il sigillo;Suggerimento: Consacrazione solo con mana sufficiente, Benedizione della Potenza per te"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "Valori: colpire fino a +9 %, agilità (1 PA, circa 29 = 1 % critico), PA, critico;Arma: combattimento = mano secondaria veloce, mano principale lenta (Colpo Sinistro); pugnali per Pugnalata;Rotazione: accumula punti combo, mantieni Affettare, poi Sventramento;Suggerimento: con due armi i colpi normali mancano più spesso - colpire è la cosa più importante"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "Valori: colpire fino a +9 %, agilità (2 PA a distanza, circa 53 = 1 % critico), PA, intelletto;Arma: arma a distanza lenta (molto danno per colpo), arma da mischia con valori;Rotazione: Marchio del Cacciatore, Tiro Automatico, Tiro Mirato/Tiro Multiplo in mezzo;Suggerimento: nutri il famiglio e tienilo felice, Trappola Congelante (quadrato) come controllo"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "Valori: colpire fino a +9 %, forza (1 punto = 2 PA), critico (circa 20 agilità = 1 %);Arma: arma a due mani lenta (Colpo Mortale, Colpo Eroico agiscono per colpo);Rotazione: accumula ira, Colpo Mortale / Sete di Sangue, Turbine, ira in eccesso in Colpo Eroico;Suggerimento: Grido di Battaglia prima del combattimento, Esecuzione sotto il 20 % di vita"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "Valori: difesa (440 = immune ai critici dei boss al 60), tempra, armatura, blocco con scudo;Arma: arma a una mano + scudo, arma veloce = più ira;Rotazione: Colpo di Scudo/Vendetta, Squarcia Armatura sul bersaglio, Colpo Eroico con molta ira;Suggerimento: colpire aiuta affinché Provocazione e abilità non manchino"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "Valori: difesa, tempra, armatura, poi danni magici per più minaccia;Arma: arma a una mano (meglio con danni magici) + scudo;Rotazione: Furia Giusta attiva, Consacrazione per i gruppi, mantieni Scudo Sacro;Suggerimento: il mana scarseggia - porta Sigillo della Saggezza o intelletto"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "Valori: danni magici, critico magico (Focus Elementale risparmia mana), intelletto, rigen. mana;Arma: arma a una mano + scudo/mano secondaria con danni magici;Rotazione: spamma Fulmine, Catena di Fulmini sui gruppi, Scossa di Fiamma;Suggerimento: colpire magico fino a +16 % in incursione, Totem della Fonte di Mana contro il mana vuoto"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "Valori: danni magici, critico magico, intelletto, colpire magico fino a +16 % in incursione;Arma: bastone o arma a una mano + mano secondaria con danni magici;Rotazione: Fuoco Lunare + Sciame di Insetti, poi Ira o Fuoco Stellare;Suggerimento: Innervazione su di te quando il mana scarseggia"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "Valori: danni magici, colpire magico fino a +16 % (incursione), tempra, intelletto;Arma: bastone o pugnale + mano secondaria con danni magici, bacchetta per il mana residuo;Rotazione: Corruzione + maledizione, poi Dardo d'Ombra; Prelievo di Vita invece di bere;Suggerimento: la tempra vale doppio (Prelievo di Vita, Ombra del Vuoto/Legame d'Anima)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "Valori: danni magici, colpire magico fino a +16 % (incursione), spirito per il mana;Arma: bastone o arma a una mano + mano secondaria con danni magici;Rotazione: Parola d'Ombra: Dolore, Assalto Mentale, Flagello Mentale;Suggerimento: Forma d'Ombra sempre attiva, Abbraccio Vampirico cura il gruppo"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "Valori: danni magici, poi colpire magico fino a +16 % (boss d'incursione), intelletto, critico magico;Arma: bastone con danni magici, più una bacchetta per il mana residuo;Rotazione: spamma Dardo di Gelo o Palla di Fuoco, Evocazione con mana vuoto;Livellare: intelletto e spirito = meno pause, in gruppo usa Pecora (luna)"
