T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Mostra MIGLIORE / PEGGIORE / NON INDOSSABILE con effetto (DPS, vita, armatura) e tabella valori. Il confronto Blizzard appare allora solo con Maiusc. Se è caricato nesUI con un proprio confronto, Oasis non mostra nulla (altrimenti doppio) - disattivalo lì con /nes vergleich."
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Mostra Migliore / Peggiore / Non indossabile con effetto (DPS, vita, armatura) e tabella valori. Il confronto Blizzard appare allora solo con Maiusc. Se è caricato nesUI con un proprio confronto, Oasis non mostra nulla (altrimenti doppio) - disattivalo lì con /nes vergleich."
T["Zeigt Beute aus Dungeons deines Levelbereichs, die besser ist als dein angelegtes Teil."] = "Mostra bottino dalle spedizioni del tuo intervallo di livello migliore del pezzo indossato."
T["Zeigt ab Oasis-Rang 30 ein Juwel und ab Rang 70 einen schimmernden Namen im Oasis-Gildenchat"] = "Mostra una gemma dal rango Oasis 30 e un nome scintillante dal rango 70 nella chat di gilda Oasis"
