T["Zeigt im Brachland ab und zu typische Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "Nelle Savane mostra ogni tanto frasi tipiche nella chat generale - Chuck Norris, la moglie di Mankrik ... Solo per te, nulla viene inviato."
