T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  Tieni attivo il registro di combattimento (Impostazioni > Aree > Classifica combattimento, attivo di base).\n2.  Dopo aver giocato, fai doppio clic su ImportCrits.bat nella cartella Oasis.\n3.  /reload in gioco - il tuo critico più alto appare qui e viene condiviso con la gilda."
