T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "Attivo: suoni meme, musica ed emoji di gilda sono inclusi."
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "I membri attivi sotto i gradi da ufficiale compaiono nella lista 'Promozione' dopo tanti giorni nello stesso grado. 0 = off."
T["Aktuelles Gebiet zuerst"] = "Prima la zona attuale"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "Tutte le aree, raggruppate per tema: gilda, giocare insieme, incursione, commercio, divertimento. Clicca un titolo per chiudere il gruppo."
T["Alle Gebiete aufklappen"] = "Espandi tutte le zone"
T["Alle Gebiete zuklappen"] = "Comprimi tutte le zone"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "Tutti i membri con grado, livello e versione di Oasis. Clic destro su una riga: cambia grado."
T["Alle Schriften unter der SIL Open Font License 1.1"] = "Tutti i caratteri sotto SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Burning Adrenaline: correte SUBITO fuori dall'incursione (state per morire).\nAll: Risorse piene all'inizio - usate tutto.\nTank: Stabilite l'ordine dei tank (Adrenaline sul tank).\nDD: Non davanti né dietro al drago."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Non fate morire gli 8 Firesworn vicino all'incursione (esplosione).\nTank: Ogni tank degli add porta via il suo Firesworn, gli stregoni esiliano.\nHealer: Dissolvete, occhio ai tank degli add.\nDD: Prima Garr, gli add solo su ordine."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Tankate i due Core Rager lontano dal boss, non uccideteli.\nTank: Cambiate il tank di Golemagg quando Magma Splash si accumula troppo.\nDD: Solo su Golemagg."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: Prima i 4 sacerdoti, si curano a vicenda.\nTank: Tenete separati Sulfuron e i sacerdoti.\nDD: Interrompete! Fermate Dark Mending dei sacerdoti."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: Protezione dal fuoco! Wrath of Ragnaros respinge la mischia - poi tornate sotto.\nAll: Fase dei Figli (dopo 3 min o quando si immerge): uccidete tutti i Figli della Fiamma.\nTank: Secondo tank pronto quando il primo viene respinto.\nHealer: Sparsi, a distanza non troppo vicini (Lava Burst).\nDD: Mischia: mana sotto controllo, a distanza state lontani."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet si accumula - a distanza dietro le colonne per farlo svanire.\nTank: Due tank dietro le colonne, Wing Buffet respinge.\nDD: Mantello di Scaglie di Onyxia obbligatorio."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Rimuovete subito Gehennas' Curse (cure ridotte).\nAll: Uscite da Pioggia di Fuoco.\nTank: Tankate separati i due Flamewaker.\nDD: Prima i Flamewaker, poi Gehennas."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Rimuovete subito Lucifron's Curse e Impending Doom (maghi/druidi, sacerdoti/paladini).\nTank: Tankate separate le due guardie - controllo mentale!\nHealer: State sparsi, dissolvete i giocatori sotto controllo mentale.\nDD: Prima le guardie, poi Lucifron."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Bomba Vivente: correte SUBITO fuori dall'incursione!\nAll: Inferno - via dal boss, dissolvete Ignite Mana.\nTank: Tenete il centro, uscite un attimo durante Inferno.\nDD: Mischia indietro durante Inferno."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Occhio al riflesso magico/scudo di danno delle guardie - allora fermate i danni.\nTank: Una guardia per tank, i maghi trasformano in pecora le guardie élite.\nDD: Prima le guardie guaritrici (Flamewaker Healer)."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Mai davanti o dietro a Onyxia (soffio e colpo di coda).\nAll: Fase 2 (65%): schivate le palle di fuoco, fuori dagli ingressi delle grotte.\nAll: Fase 3 (40%): paura - Fear Ward/Totem del Tremore pronti, evitate le crepe di lava.\nTank: Onyxia di lato contro il muro, testa lontana dall'incursione.\nTank: Fase 2: raccogliete i cuccioli. Fase 3: riprendete subito l'aggro.\nHealer: Il tank ha la priorità, in fase 2 state sparsi.\nDD: Aspettate 3 attacchi del tank. Fase 2: prima i cuccioli."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Panico - Fear Ward/Totem del Tremore, cacciatori: Tiro Tranquillizzante su Frenesia.\nAll: Uscite dal fuoco di lava a terra.\nTank: Magmadar di spalle all'incursione.\nDD: A distanza sparsi in fondo."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Fase 1: dragonidi da entrambi i lati, occhio ai richiami di classe.\nAll: Fase 3 (20%): gli scheletri risorgono - uccideteli di nuovo.\nTank: Nefarian contro il muro, paura - Fear Ward.\nHealer: Richiamo di classe per i sacerdoti: le cure fanno danno - attenti.\nDD: Cacciatori/guerrieri: occhio ai richiami di classe (armi via, postura)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Fase 1: distruggete le uova (controllo mentale tramite il globo), prendete gli add.\nAll: Dopo tutte le uova: boss nella stanza - Fire Nova.\nTank: Radunate gli add alle scale.\nDD: Prima maghi e dragonidi."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Frenesia - cacciatori: Tiro Tranquillizzante.\nTank: Due tank, occhio a Wing Buffet.\nDD: Mantello di Scaglie di Onyxia obbligatorio."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Shadow of Ebonroc cura il boss - il tank con il debuff fa cambio.\nTank: Due tank si scambiano con Shadow.\nDD: Mantello di Scaglie di Onyxia obbligatorio."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Contraccolpo - mettetevi contro il muro.\nTank: Due tank, l'aggro viene diviso da Knock Away.\nDD: Assalto Mortale sul tank: guaritori pronti."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: Si teletrasporta - chi ha l'aggro non scappi.\nAll: Rimuovete Shazzrah's Curse, Esplosione Arcana: mischia a distanza.\nTank: Tornategli addosso subito dopo ogni traslazione.\nHealer: Dissolvete (Deaden Magic)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Due dei cinque tipi di soffio a settimana - evitate il soffio dietro l'angolo.\nAll: Hourglass Sand per l'afflizione di bronzo.\nTank: Tankate al cancello, incursione dietro l'angolo.\nDD: Tiro Tranquillizzante su Frenesia."
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "Tieni Alt: tutti i valori e la valutazione. Maiusc: confronto Blizzard."
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "Rilascia Alt: vista compatta. Maiusc: confronto Blizzard."
