T["Das X am Fenster klappt Oasis in die Leiste ein. Das X an der Leiste schliesst ganz."] = "La X sulla finestra riduce Oasis nella barra. La X sulla barra lo chiude del tutto."
T["Das gelbe Ausrufezeichen am Symbol zeigt das an."] = "Lo indica il punto esclamativo giallo sull'icona."
T["Das war nur Glueck! Nochmal!"] = "Solo fortuna! Ancora!"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "Tutto qui. Ritrovi il tour quando vuoi in Impostazioni > Stato o con /oa rundgang."
T["Daten"] = "Dati"
T["Deckend"] = "Opaco"
T["Dein Charakter"] = "Il tuo personaggio"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "Le tue statistiche: grado Oasis, distintivi e tutti i contatori"
T["Den Download findest du im Discord der Gilde."] = "Trovi il download nel Discord della gilda."
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "Il client non permette a Oasis di attivare il registro di combattimento - digita tu /combatlog."
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "Il contenuto dell'area scelta. La panoramica mostra chi è online, cosa è in programma e cosa c'è di nuovo."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "Il pulsante della minimappa o /oa apre Oasis. Con il trattino in alto a destra la finestra diventa una barra sottile."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "Il canale ufficiali (/o) con cronologia - solo per i gradi con permesso di chat ufficiali."
T["Der gelbe Strich links in der Liste zeigt das an."] = "Lo indica la barra gialla a sinistra nella lista."
T["Details schliessen"] = "Chiudi dettagli"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "Suono predefinito più chiaro per gli avvisi online"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "Le statistiche del personaggio non sono disponibili in questo client."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "La direzione della gilda ti ha bloccato gli effetti sonori."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "La barra c'è dall'accesso e resta - la X sulla finestra chiude solo la finestra."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "La percentuale confronta il punteggio dell'oggetto per il tuo ruolo, non il tuo danno totale. Gli effetti sono stime."
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "La statistica al momento non fornisce un valore leggibile."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "Il centro della vostra gilda. In 30 secondi saprai orientarti - ecco l'essenziale."
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "La funzione protetta è stata bloccata. La causa esatta è ancora sconosciuta."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "La statistica del personaggio adatta non è ancora stata trovata."
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "I testi completi delle licenze sono nella cartella Oasis: CREDITS.txt, LICENSE e LICENSE-MIT.txt."
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "Questi gradi di gilda (0 = capogilda) possono votare nel consiglio del bottino."
T["Dieser Charakter liegt auf einem anderen WoW-Account und hat dich als Main eingetragen. Nur wenn du bestaetigst, zaehlt er in der Gilde als dein Twink."] = "Questo personaggio è su un altro account WoW e ti ha indicato come main. Conta come tuo alt in gilda solo se confermi."
T["Dieser Client liefert keine Addon-Messwerte (C_AddOnProfiler fehlt)."] = "Questo client non fornisce metriche degli addon (manca C_AddOnProfiler)."
T["Discord Voice"] = "Discord Voice"
T["Discord Voice: an"] = "Voce Discord: attiva"
T["Discord-Link (kommt in die Nachricht)"] = "Link Discord (va nel messaggio)"
T["Discord: %s"] = "Discord: %s"
T["Discord: %s  -  %d im Voice"] = "Discord: %s  -  %d in voce"
T["Download: %s"] = "Download: %s"
T["Drop %s %%"] = "Drop %s %%"
T["Du nix Kerze nehmen!"] = "Tu no prende candela!"
T["Du wirst sterben."] = "Morirai."
T["Durchsage schreiben"] = "Scrivi un annuncio"
T["Durchsichtig"] = "Trasparente"
T["Echtzeit, aktualisiert jede Sekunde - Oasis und Gildenmodul zusammen"] = "In tempo reale, aggiornato ogni secondo - Oasis e modulo di gilda insieme"
T["Eigene Arbeit"] = "Lavoro proprio"
T["Eine Einstellung wurde waehrend einer geschuetzten Aktion geaendert."] = "Un'impostazione è stata modificata durante un'azione protetta."
T["Eine Nachricht an alle mit Oasis - mit Hinweis und Ton."] = "Un messaggio a tutti quelli con Oasis - con avviso e suono."
T["Eine Taschenaktion wurde blockiert."] = "Un'azione sulle borse è stata bloccata."
T["Eingeklappt"] = "Compresso"
T["Einklappen"] = "Comprimi"
T["Einklappen, verschieben, ausblenden"] = "Comprimi, sposta, nascondi"
T["Einsteiger-Einstellungen gesetzt: ruhigere Hinweise, weniger Seiten. Seiten wieder einblenden unter Einstellungen > Bereiche. Bitte /reload."] = "Impostazioni per principianti applicate: avvisi più tranquilli, meno pagine. Per mostrare di nuovo le pagine: Impostazioni > Aree. Fai /reload."
T["Einstellungen und Sprache"] = "Impostazioni e lingua"
T["Einzelrekorde werden aus den Charakterstatistiken gelesen. Noch kein lesbarer Wert vorhanden."] = "I record di colpo singolo vengono letti dalle statistiche del personaggio. Nessun valore leggibile per ora."
T["Emojis, Copyright Twitter/X und Mitwirkende - CC BY 4.0, fuer Oasis verkleinert"] = "Emoji, copyright Twitter/X e collaboratori – CC BY 4.0, ridimensionate per Oasis"
T["Entwuerfe je Gespraech merken"] = "Ricorda le bozze per conversazione"
T["Entzaubern ergibt"] = "Disincantando ottieni"
T["Erstes Gebot je Item in Gold."] = "Prima offerta per oggetto, in oro."
T["Erzlich von Naxxramas"] = "Arcilich di Naxxramas"
T["Esc-Taste: Blizzards Esc-Weg war von Oasis beruehrt (ab 0.5.478 behoben - bitte Oasis aktualisieren)."] = "Tasto Esc: la gestione di Esc di Blizzard era stata toccata da Oasis (risolto dalla 0.5.478 - aggiorna Oasis)."
T["Etwas groesser"] = "Un po' più grande"
T["Faire Beute: wer oft dabei ist und wenig bekommen hat, ist zuerst dran"] = "Bottino equo: chi partecipa spesso e ha ricevuto poco passa per primo"
T["Federn der Harpyie"] = "Piume d'arpia"
T["Flaggen von Panayiotis Lipiridis - MIT-Lizenz"] = "Bandiere di Panayiotis Lipiridis – licenza MIT"
T["Fluester-Angebot fuer Twinks: an"] = "Offerta sussurro per alt: on"
T["Fluester-Angebot fuer Twinks: aus"] = "Offerta sussurro per alt: off"
T["Fluestern an Offline-Charaktere dem Twink anbieten"] = "Proponi all'alt i sussurri a personaggi offline"
T["FojjiCore %s erkannt - Journal, Karten und Routen oeffnet Oasis dort."] = "FojjiCore %s rilevato - Oasis apre lì diario, mappe e percorsi."
T["FojjiCore ist nicht geladen - Oasis laeuft eigenstaendig."] = "FojjiCore non è caricato - Oasis funziona da solo."
T["Frei verschiebbar"] = "Spostabile liberamente"
T["Frei verschieben (mit der Maus ziehen)"] = "Sposta liberamente (trascina col mouse)"
T["Fuer diesen Boss gibt es noch keine Taktik."] = "Nessuna tattica per questo boss, per ora."
T["G%d"] = "G%d"
T["GDKP: Anteil Gildenbank"] = "GDKP: quota banca di gilda"
T["GNU General Public License Version 2 (GPL-2.0). Oasis darf weitergegeben und veraendert werden, solange diese Lizenz erhalten bleibt."] = "GNU General Public License versione 2 (GPL-2.0). Oasis può essere condiviso e modificato purché questa licenza venga mantenuta."
T["Gack. Gack gack."] = "Coccodè. Coccodè coccodè."
T["Gerade ist niemand im Sprachkanal."] = "Al momento non c'è nessuno nel canale vocale."
T["Gesamte Beute"] = "Tutto il bottino"
T["Gesperrte koennen keine Soundeffekte mehr senden, und bei allen anderen bleiben ihre Sounds stumm. Gilt auch fuer ihre Twinks."] = "Chi è bloccato non può più inviare effetti sonori, e i suoi suoni restano muti per tutti gli altri. Vale anche per i suoi alt."
T["Gespraeche mit Twinks haengen aufklappbar unter dem Gespraech mit ihrem Main"] = "Le conversazioni con gli alt stanno, espandibili, sotto quella con il loro main"
T["Gewinnen ist einfach. Nochmal?"] = "Vincere è facile. Ancora?"
T["Gezaehlt wird dein bester einzelner Kampf, egal wo. Der Ort daneben zeigt, wo dieser Kampf war."] = "Conta il miglior combattimento singolo di ogni giocatore, ovunque. Il luogo accanto mostra dove è avvenuto."
T["Gezaehlt wird der beste einzelne Kampf je Spieler - egal ob Dungeon oder offene Welt."] = "Conta il miglior combattimento singolo di ogni giocatore - spedizione o mondo aperto."
T["Gilde diese Woche: +%d Ruf"] = "Gilda questa settimana: +%d reputazione"
T["Gilden-Sammelkarte: Fundorte, die jemand aus der Gilde gefunden hat"] = "Mappa di raccolta di gilda: punti trovati da qualcuno della gilda"
T["Gildenevents"] = "Eventi di gilda"
T["Gildenmodul"] = "Modulo di gilda"
T["Gildenpflege: Inaktive finden, Befoerderungen, Verlauf, Ehemalige, Bewerber und Bannliste."] = "Cura della gilda: trova inattivi, promozioni, cronologia, ex membri, candidati e lista dei bannati."
T["Gildenpflege: Inaktive finden, Befoerderungen, Verlauf, Ehemalige, Bewerber, Bannliste und Sound-Sperren."] = "Cura della gilda: trova inattivi, promozioni, cronologia, ex membri, candidati, lista dei bannati e blocchi audio."
T["Gnomeregan war mal schoen"] = "Gnomeregan una volta era bella"
