T["Ist %s dein Twink?"] = "%s è un tuo alt?"
T["Ist FojjiCore installiert, oeffnet Oasis dessen Dungeon-Journal und kann dessen Wunschliste uebernehmen"] = "Se FojjiCore è installato, Oasis apre il suo diario delle spedizioni e può importarne la lista desideri"
T["Ist der angefluesterte Charakter offline und ein Twink desselben Spielers online, bietet Oasis an, die Nachricht dorthin zu schicken - gesendet wird erst nach deinem Klick."] = "Se il personaggio a cui sussurri è offline e un alt dello stesso giocatore è online, Oasis propone di inviare lì il messaggio - parte solo dopo il tuo clic."
