T["Kommt ein ehemaliges Mitglied zurueck, bekommt die Gildenleitung einen Hinweis mit dem frueheren Rang und Austrittsdatum."] = "Se un ex membro ritorna, la direzione della gilda riceve un avviso con il suo vecchio grado e la data di uscita."
