T["Kriegshaeuptling der Horde"] = "Capoguerra dell'Orda"
T["Kurze Taktik je Boss, nach Rollen - mit einem Klick in den Raidchat"] = "Tattica breve per boss, per ruolo - con un clic nella chat d'incursione"
T["Lege Termine und Gildenevents an - sie erscheinen bei allen im Dashboard."] = "Crea appuntamenti ed eventi di gilda - compaiono nella dashboard di tutti."
T["Lege fest, welche Bereiche von Oasis die Gilde sieht und ab welchem Rang. Danach unten speichern."] = "Decidi quali aree di Oasis vede la gilda e da quale grado. Poi salva in basso."
T["Lege fest, welcher Rang was darf (Durchsagen, Termine, Bank ...). Danach unten speichern."] = "Decidi quale grado può fare cosa (annunci, eventi, banca ...). Poi salva in basso."
