T["Neben dem Talentfenster zeigen"] = "Mostra accanto alla finestra dei talenti"
T["Nein, kenne ich nicht"] = "No, non lo conosco"
T["Neueste in der Gilde: v%s"] = "Più recente in gilda: v%s"
T["Nicht enthalten (oeffentliche Version): Meme-Sounds, Musik und Gilden-Emojis gibt es nur in der Gildenversion."] = "Non incluso (versione pubblica): suoni meme, musica ed emoji di gilda ci sono solo nella versione di gilda."
T["Nicht gefunden"] = "Non trovato"
T["Niemand ist fuer Soundeffekte gesperrt."] = "Nessuno è bloccato per gli effetti sonori."
T["Niemand online"] = "Nessuno online"
T["Noch eine Runde - ich will meine Ehre zurueck!"] = "Un altro giro - rivoglio il mio onore!"
T["Noch kein Crit erfasst. Kritische Treffer zaehlen automatisch, sobald du allein in der offenen Welt kaempfst."] = "Nessun critico registrato. I colpi critici contano in automatico quando combatti da solo nel mondo aperto."
T["Noch kein Termin geplant. Oben links: Was, Tag, Uhrzeit - dann 'Event anlegen'."] = "Nessun evento pianificato. In alto a sinistra: cosa, giorno, ora - poi 'Crea evento'."
T["Noch kein lesbarer eigener Crit erfasst. Neue kritische Treffer werden automatisch aufgezeichnet."] = "Nessun tuo critico leggibile registrato per ora. I nuovi colpi critici vengono registrati in automatico."
T["Noch kein positiver Einzelrekord gemeldet."] = "Nessun record positivo di colpo singolo segnalato per ora."
T["Noch keine Durchsagen. Schreib links die erste - Ueberschrift, Nachricht, senden."] = "Nessun annuncio ancora. Scrivi il primo a sinistra - titolo, messaggio, invia."
T["Noch keiner bestaetigt - der Twink traegt dich mit /oa twink als Main ein."] = "Nessuno confermato ancora - l'alt ti imposta come main con /oa twink."
T["Nur Helfer online"] = "Solo aiutanti online"
T["Nur aktuelles Gebiet"] = "Solo zona attuale"
T["Nur falls WoW die Rang-Rechte nicht liefert: bis zu welchem Gildenrang andere als Offizier gelten (fuer die Pruefung empfangener Daten)."] = "Solo se WoW non fornisce i permessi dei gradi: fino a quale grado di gilda gli altri valgono come ufficiali (per verificare i dati ricevuti)."
T["Nur geoeffnete"] = "Solo aperte"
T["Nur wenn er Oasis hat - sonst bleibt die Reaktion bei dir"] = "Solo se ha Oasis - altrimenti la reazione resta da te"
