T["Oasis: Alarm 2"] = "Oasis: Allarme 2"
T["Oasis: Fenster auf"] = "Oasis: Apri finestra"
T["Oasis: Fenster zu"] = "Oasis: Chiudi finestra"
T["Oeffnet diesen Dungeon im Journal von FojjiCore: Karten, Routen, Drop-Chancen."] = "Apre questa spedizione nel diario di FojjiCore: mappe, percorsi, probabilità di drop."
T["Offene Gruppensuchen der Gilde - Klick: Gruppen"] = "Ricerche di gruppo aperte della gilda - clic: Gruppi"
T["Offiziere bis Gildenrang (Ersatz)"] = "Ufficiali fino al grado di gilda (riserva)"
T["Ohne Gruppe und ausserhalb von Dungeons zaehlt jeder kritische Treffer auf dein Ziel sofort fuer Hoechster Crit - ohne Logdatei."] = "Senza gruppo e fuori dalle spedizioni, ogni colpo critico sul tuo bersaglio conta subito per Critico più alto - senza file di registro."
T["Pause"] = "Pausa"
T["Plaetze"] = "Posti"
T["Privat: Twink-Gespraeche unter dem Main"] = "Privato: conversazioni con alt sotto il main"
