T["Quelle: Blizzards Schadensanzeige."] = "Fonte: contatore danni di Blizzard."
T["Quelle: Charakterstatistik. Crit-Status unbekannt."] = "Fonte: statistiche del personaggio. Stato critico sconosciuto."
T["Quelle: bestaetigte Crits aus Kampflog oder Logdatei."] = "Fonte: critici confermati dal registro di combattimento live o da file."
T["Quelle: eigene Crits beim Solo-Spiel. In Gruppe und Dungeon meldet WoW Addons nicht, wer getroffen hat."] = "Fonte: i tuoi critici in solitaria. In gruppo e in spedizione WoW non dice agli addon chi ha colpito."
T["Quelle: eigene Crits. Solo sicher erkannt; in Gruppe und Dungeon geschaetzt (Treffer direkt nach dem eigenen Angriff)."] = "Fonte: i tuoi critici. Affidabile in solitaria; stimato in gruppo e in spedizione (colpo subito dopo il tuo attacco)."
T["Quellen fuer Dungeons, Bosse, Beute und Quests"] = "Fonti per spedizioni, boss, bottino e missioni"
T["Questbelohnung: beste Wahl markieren"] = "Ricompensa missione: evidenzia la scelta migliore"
T["Quests & Karte"] = "Missioni e mappa"
T["Raid auswerten"] = "Analizza incursioni"
T["Raid, Gildenabend oder Event eintragen, sichtbar fuer alle."] = "Inserisci un'incursione, una serata di gilda o un evento, visibile a tutti."
T["Raid-Gruppen lassen sich im Kampf nicht umsortieren."] = "I gruppi dell'incursione non si possono riordinare in combattimento."
T["Raid: wer war dabei und wie gut ist die Ausruestung der Gilde."] = "Incursione: chi c'era e quanto è buono l'equipaggiamento della gilda."
T["Rang aendern, befoerdern, zurueckstufen und mehr"] = "Cambia grado, promuovi, retrocedi e altro"
T["Rang-Wappen, Profilrahmen, Stufen-Abzeichen, Wappen, Ziffern, Deathroll-Grafiken, Logos, Effekte und Designs stammen vom Oasis-Autor. Die Dashboard-Banner hat der Autor mit KI erstellt."] = "Stemmi di grado, cornici del profilo, distintivi di livello, emblemi, cifre, grafiche Deathroll, loghi, effetti e temi sono dell'autore di Oasis. I banner della dashboard sono stati creati dall'autore con l'IA."
T["Reaktionen an den Gespraechspartner schicken"] = "Invia le reazioni al tuo interlocutore"
T["Rechenzeit jetzt"] = "Tempo di calcolo ora"
T["Rechte vergeben"] = "Assegna permessi"
T["Respec ab 1 Punkt, stuendlich 1 guenstiger"] = "respec da 1 punto, 1 in meno ogni ora"
