T["Uebernimmt, was du in FojjiCores Wunschliste markiert hast. Die Gilde sieht diese Wuensche dann hier."] = "Copia ciò che hai segnato nella lista desideri di FojjiCore. La gilda vede poi questi desideri qui."
T["Um so viel Gold muss jedes neue Gebot hoeher sein."] = "Ogni nuova offerta deve superare la precedente di tanto oro."
