T["Vorschlaege, wer einen hoeheren Rang verdient hat."] = "Suggerimenti su chi merita un grado più alto."
T["Wache von Orgrimmar"] = "Guardia di Orgrimmar"
T["Waehle unten, was du tun moechtest - Oasis bringt dich an die richtige Stelle."] = "Scegli qui sotto cosa vuoi fare - Oasis ti porta nel posto giusto."
T["Wartet auf einen Kuss"] = "Aspetta un bacio"
T["Was die Leitung geaendert hat, Auffaelligkeiten, Daten sichern."] = "Cosa ha cambiato la direzione, anomalie, backup dei dati."
T["Was du fuer den naechsten Raid noch brauchst - Widerstaende, Verbrauchsgueter, Haltbarkeit, Schluessel"] = "Cosa ti serve ancora per la prossima incursione - resistenze, consumabili, durabilità, chiavi"
T["Was liegt wo? Suche ueber alle deine Charaktere, ihre Bank und die Gildenbank"] = "Cosa c'è e dove? Cerca tra tutti i tuoi personaggi, la loro banca e la banca di gilda"
T["Was moechtest du tun?"] = "Cosa vuoi fare?"
T["Was?"] = "Cosa?"
T["Weitere Gildenevents folgen hier."] = "Altri eventi di gilda seguiranno qui."
T["Weitere Plaetze fuellen sich, sobald mehr Gildenmitglieder mit Oasis gekaempft haben."] = "Altri posti si riempiono quando più membri della gilda con Oasis avranno combattuto."
T["Weitere Upgrades in diesem Dungeon"] = "Altri miglioramenti in questa spedizione"
T["Welche Seiten sieht die Gilde - und ab welchem Rang."] = "Quali pagine vede la gilda - e da quale grado."
T["Welcher Rang darf Durchsagen, Termine, Bank und mehr."] = "Quale grado può usare annunci, eventi, banca e altro."
T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "Chi in una serata ha già ricevuto un oggetto per necessità passa, per necessità, dietro a tutti quelli senza oggetto (a parità di tiro)."
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "Chi ha prenotato un oggetto per l'evento passa davanti a tutti per necessità."
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "Chi ha quali potenziamenti in gruppo o incursione - e chi può dare ciò che manca"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "Chi è in gilda, con quale grado, chi ha un Oasis vecchio."
T["Wer war lange nicht online - aufraeumen mit einem Klick."] = "Chi non è online da tempo - fai pulizia con un clic."
T["Wie die Schrift"] = "Come il testo"
T["Wieder am Talentfenster andocken"] = "Riaggancia alla finestra dei talenti"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "In gruppo WoW non dice agli addon chi ha colpito. Oasis conta un colpo critico solo se segue subito il tuo attacco e, dopo il combattimento, corrisponde al contatore danni. In classifica è segnato come stimato."
T["WoW-Klassiker"] = "Classici di WoW"
T["Wochenaufgaben %d/%d"] = "Compiti settimanali %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft e i relativi nomi, stemmi e grafiche sono marchi di Blizzard Entertainment. Oasis è un progetto di fan e non è affiliato a Blizzard."
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "Tiro: ordine necessità > seconda spec > transmog, poi il tiro. Punti: decide la priorità dai punti bottino. Consiglio del bottino: gli ufficiali votano, il responsabile del bottino assegna."
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "Ingranaggio = impostazioni (aspetto, suoni, avvisi). Accanto la lingua e - per la direzione della gilda - la corona."
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "Mostra quali materiali si possono ottenere disincantando oggetti verdi, blu ed epici"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "Mostra nella ricerca che parlate a voce (Discord ecc.). L'ingresso resta gestito da Blizzard / dal tuo capogruppo."
T["Zeigt nur Mains. Twinks sind Charaktere, die einem anderen Main zugeordnet sind."] = "Mostra solo i main. Gli alt sono personaggi assegnati a un altro main."
T["Zeigt nur die Kopfzeile mit der Anzahl der Builds."] = "Mostra solo l'intestazione con il numero di build."
T["Zeigt sofort, wer aus der Gilde dieselben Quests hat und gerade online ist - ein Klick laedt ihn ein."] = "Mostra subito chi in gilda ha le stesse missioni ed è online ora - un clic lo invita."
T["Zielt jemand einen Boss an, zu dem es eine Taktik gibt, erscheint ein kurzer Hinweis (ausserhalb des Kampfes)."] = "Se qualcuno prende a bersaglio un boss con una tattica, appare un breve avviso (fuori dal combattimento)."
T["Zu leicht. Traust du dich nochmal?"] = "Troppo facile. Hai il coraggio di riprovare?"
T["Zufaelliger Gruss, wenn jemand online kommt"] = "Saluto casuale quando qualcuno va online"
T["Zweiklang statt kurzem Ton, wenn die Person keinen eigenen Online-Sound gewaehlt hat"] = "Doppio tono invece di un suono breve se la persona non ha scelto un suono online"
